def create_item(
    self,
    vault_id: int,
    service: str,
    secret_fields: dict[str, str],
    tags: list[str] | None = None,
) -> dict[str, Any]:
    kek = self._require_unlocked()
    envelope = build_envelope(secret_fields, kek)
    return cast(
        dict[str, Any],
        self._request(
            "POST",
            f"/api/vaults/{vault_id}/items",
            json={
                "vault": vault_id,
                "service": service,
                "tags": tags or [],
                "envelope": envelope.to_dict(),
            },
        ),
    )

